<?php
namespace App\Http\Controllers; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Str; use Illuminate\Validation\Rule;
class UserController extends Controller { public function index(){return view('users.index',['users'=>User::orderBy('name')->get()]);} public function store(Request $request){$data=$request->validate(['name'=>'required|string|max:100','email'=>'required|email|unique:users,email','role'=>['required',Rule::in(['admin','manager','staff'])]]);$data['email']=strtolower($data['email']);$data['password']=Hash::make(Str::random(40));$data['is_active']=true;User::create($data);return back()->with('success','User authorised. They can now request an email OTP.');} public function update(Request $request,User $user){$data=$request->validate(['role'=>['required',Rule::in(['admin','manager','staff'])],'is_active'=>'required|boolean']);abort_if($user->is($request->user())&&!$data['is_active'],422,'You cannot deactivate your own account.');$user->update($data);return back()->with('success','User access updated.');} }
